    "    def toJsConfig(incoming: js.Dynamic): js.Dynamic = {",
    "      val encoded = js.Dynamic.literal()",
    "      copyDynamicFields(encoded, incoming)",
    "",
    "      val resolvedNetwork = network.getOrElse(",
